WITH src AS (SELECT * FROM store_sales WHERE units >= 21), SaleCohortSummary AS (SELECT CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, MAX(sale_date) AS last_sale_date FROM src GROUP BY CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT sale_cohort, last_sale_date FROM SaleCohortSummary ORDER BY 2 ASC, sale_cohort ASC LIMIT 1
